<?php
require_once __DIR__ . '/../config/config.php';
require_login();
$user = current_user();
$isStaff = in_array($user['role'], ['admin','staff'], true);
$pdo = db();
function create_notification(int $recipientId, string $title, string $message, string $url, string $type = 'general', ?int $requestId = null): void {
    $stmt = db()->prepare('INSERT INTO user_notifications (recipient_user_id, title, message, target_url, notification_type, related_request_id) VALUES (?, ?, ?, ?, ?, ?)');
    $stmt->execute([$recipientId, mb_substr($title, 0, 160), mb_substr($message, 0, 500), $url, $type, $requestId]);
}

$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$stmt = $pdo->prepare('SELECT r.*, u.full_name AS customer_name, u.email AS customer_email, u.phone AS customer_phone, s.name AS service_name, a.full_name AS assignee_name FROM service_requests r JOIN users u ON u.id=r.customer_id LEFT JOIN services s ON s.id=r.service_id LEFT JOIN users a ON a.id=r.assigned_to WHERE r.id=? LIMIT 1');
$stmt->execute([$id]);
$ticket = $stmt->fetch();
if (!$ticket || (!$isStaff && (int)$ticket['customer_id'] !== (int)$user['id'])) { http_response_code(404); exit('Ticket not found or access denied.'); }
$error=''; $success='';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  if (!verify_csrf()) $error='Your session token expired. Refresh the page and try again.';
  elseif (isset($_POST['send_reply'])) {
    $body=trim((string)($_POST['body'] ?? ''));
    if ($body==='' || mb_strlen($body)>5000) $error='Enter a reply of 1–5,000 characters.';
    else {
      $ins=$pdo->prepare('INSERT INTO service_request_messages (request_id,sender_user_id,body) VALUES (?,?,?)');
      $ins->execute([$id,(int)$user['id'],$body]);
      if ($isStaff && $ticket['status']==='new') { $up=$pdo->prepare("UPDATE service_requests SET status='in_progress' WHERE id=?"); $up->execute([$id]); }
      log_activity((int)$user['id'],'ticket_reply','Reply added to ticket '.$ticket['request_code'],'service_request',$id);
      header('Location: '.BASE_URL.'/request-view.php?id='.$id.'&sent=1'); exit;
    }
  } elseif ($isStaff && isset($_POST['update_ticket'])) {
    $status=(string)($_POST['status'] ?? ''); $allowed=['new','in_progress','waiting_customer','completed','cancelled'];
    $assignee=filter_var($_POST['assigned_to'] ?? '',FILTER_VALIDATE_INT); $assignee=$assignee ?: null;
    if (!in_array($status,$allowed,true)) $error='Choose a valid status.';
    elseif ($status==='in_progress' && $assignee===null) $error='Please assign a worker before setting the request to Assigned.';
    elseif ($assignee !== null) { $check=$pdo->prepare("SELECT id FROM users WHERE id=? AND role IN ('admin','staff') AND is_active=1"); $check->execute([$assignee]); if(!$check->fetchColumn()) $error='Choose an active staff member.'; }
    if (!$error) {
      $oldStatus=(string)$ticket['status']; $oldAssignee=(int)($ticket['assigned_to'] ?? 0);
      $up=$pdo->prepare('UPDATE service_requests SET status=?, assigned_to=? WHERE id=?'); $up->execute([$status,$assignee,$id]);
      $ticketUrl=BASE_URL.'/request-view.php?id='.$id;
      if ($assignee !== null && $oldAssignee !== (int)$assignee) create_notification((int)$assignee, 'New request assigned to you', 'Request '.$ticket['request_code'].': '.$ticket['subject'].' has been assigned to you.', $ticketUrl, 'request_assigned', $id);
      if ($oldStatus !== $status) { $labels=['new'=>'Pending','in_progress'=>'Assigned','waiting_customer'=>'Waiting for customer','completed'=>'Completed','cancelled'=>'Cancelled']; create_notification((int)$ticket['customer_id'], 'Service request status updated', 'Request '.$ticket['request_code'].' is now '.($labels[$status] ?? $status).'.', $ticketUrl, 'status_changed', $id); }
      log_activity((int)$user['id'],'ticket_updated','Ticket '.$ticket['request_code'].' updated to '.$status,'service_request',$id);
      header('Location: '.BASE_URL.'/request-view.php?id='.$id.'&updated=1'); exit;
    }
  }
}
if (isset($_GET['sent'])) $success='Your reply has been sent.';
if (isset($_GET['updated'])) $success='Ticket details updated.';
$stmt=$pdo->prepare('SELECT m.*,u.full_name AS sender_name,u.role AS sender_role FROM service_request_messages m JOIN users u ON u.id=m.sender_user_id WHERE m.request_id=? ORDER BY m.created_at ASC,m.id ASC'); $stmt->execute([$id]); $messages=$stmt->fetchAll();
$staffList=$isStaff?$pdo->query("SELECT id,full_name FROM users WHERE role IN ('admin','staff') AND is_active=1 ORDER BY full_name")->fetchAll():[];
$csrf=csrf_token();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b3975"><title><?= e($ticket['request_code']) ?> | Enecom IT Solutions GH</title><link rel="manifest" href="<?= BASE_URL ?>/manifest.webmanifest"><link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/app.css"><style>
.ticket-wrap{max-width:1100px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);gap:18px}.ticket-panel{background:#fff;border:1px solid var(--line);border-radius:15px;padding:20px;min-width:0}.ticket-panel h2{margin:0 0 12px;font-size:18px}.ticket-meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ticket-meta div{background:#f5f8fd;border-radius:10px;padding:12px}.ticket-meta small{display:block;color:var(--muted);font-size:11px;margin-bottom:5px}.ticket-meta strong{overflow-wrap:anywhere}.ticket-description{white-space:pre-wrap;line-height:1.65;overflow-wrap:anywhere}.ticket-thread{display:flex;flex-direction:column;gap:12px;margin:15px 0}.ticket-message{border:1px solid #dce8f8;border-radius:12px;padding:12px 14px;background:#f8fbff}.ticket-message.staff-message{background:#eaf4ff;border-color:#c8e1ff}.ticket-message .meta{font-size:11px;color:var(--muted);display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:7px}.ticket-message .body{white-space:pre-wrap;line-height:1.55;overflow-wrap:anywhere}.ticket-reply{display:grid;gap:10px}.ticket-reply textarea{width:100%;padding:12px;border:1px solid var(--line);border-radius:10px;font:inherit;resize:vertical}.ticket-form{display:grid;gap:10px}.ticket-form select{width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;background:#fff}.phone-actions{display:flex;gap:8px;flex-wrap:wrap}.empty-thread{padding:18px;background:#f6f9fd;border-radius:10px;color:var(--muted)}@media(max-width:800px){.ticket-wrap{grid-template-columns:1fr}.ticket-meta{grid-template-columns:1fr 1fr}}@media(max-width:480px){.ticket-meta{grid-template-columns:1fr}.ticket-panel{padding:15px}}
</style></head><body>
<header class="topbar"><a class="icon-btn" href="<?= BASE_URL ?>/dashboard.php" aria-label="Back to dashboard">←</a><img class="header-logo" src="<?= BASE_URL ?>/assets/img/enecom-logo.png" alt="Enecom IT Solutions GH logo"><div class="brand-copy"><strong>ENECOM IT SOLUTIONS GH</strong><small>Technology • Training • Innovation • Solutions</small></div><div class="top-actions"><span class="role-chip"><?= e(strtoupper($user['role'])) ?></span><a class="logout" href="<?= BASE_URL ?>/logout.php">Sign out</a></div></header>
<div class="app-layout"><aside class="sidebar"><nav><a class="nav-link" href="<?= BASE_URL ?>/dashboard.php">⌂ <span>Dashboard</span></a><a class="nav-link active" href="<?= BASE_URL ?>/dashboard.php#requests">▣ <span><?= $isStaff?'Requests / Tickets':'My Requests' ?></span></a><a class="nav-link" href="<?= BASE_URL ?>/support.php">☏ <span><?= $isStaff?'Live Support Inbox':'Contact Support' ?></span></a></nav><div class="sidebar-footer"><img class="sidebar-logo" src="<?= BASE_URL ?>/assets/img/enecom-logo.png" alt="Enecom logo"><strong>ENECOM IT SOLUTIONS GH</strong><small>Ticket <?= e($ticket['request_code']) ?></small></div></aside>
<main class="main-content"><section class="notification-center" data-notification-center data-api="<?= BASE_URL ?>/notifications-api.php" data-csrf="<?= e(csrf_token()) ?>" data-icon="<?= BASE_URL ?>/assets/icons/icon-192.png"><div class="notification-heading"><div><h2>Notifications <span class="notification-count" data-notification-count hidden>0</span></h2><p class="muted">Automatic request assignment and status updates.</p></div><div class="notification-tools"><button type="button" class="btn secondary" data-enable-notifications>Enable desktop notifications</button><button type="button" class="btn secondary" data-read-all>Mark all read</button></div></div><div class="notification-list" data-notification-list><p class="muted">Loading notifications…</p></div></section><section class="welcome-row"><div><p class="eyebrow">SERVICE REQUEST / TICKET</p><h1><?= e($ticket['subject']) ?></h1><p class="muted">Reference: <?= e($ticket['request_code']) ?> · Submitted <?= e(date('d M Y, H:i',strtotime($ticket['created_at']))) ?></p></div><span class="status <?= e($ticket['status']) ?>"><?= e(ucwords(str_replace('_',' ',$ticket['status']))) ?></span></section>
<?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="notice success"><?= e($success) ?></div><?php endif; ?>
<div class="ticket-wrap"><div style="display:grid;gap:18px;align-content:start"><section class="ticket-panel"><h2>Request details</h2><div class="ticket-meta"><div><small>Customer</small><strong><?= e($ticket['customer_name']) ?></strong></div><div><small>Service</small><strong><?= e($ticket['service_name'] ?: 'General enquiry') ?></strong></div><div><small>Priority</small><strong><?= e(ucfirst($ticket['priority'])) ?></strong></div><div><small>Current status</small><strong><?= e(ucwords(str_replace('_',' ',$ticket['status']))) ?></strong></div></div><h3 style="font-size:14px;margin:18px 0 8px">Description</h3><div class="ticket-description"><?= e($ticket['description']) ?></div></section>
<section class="ticket-panel"><h2>Ticket conversation</h2><p class="muted">Use this thread so the customer and team can see replies in one place.</p><div class="ticket-thread"><?php if(!$messages): ?><div class="empty-thread">No replies yet. Send a message to start assisting with this request.</div><?php else: foreach($messages as $m): ?><article class="ticket-message <?= in_array($m['sender_role'],['admin','staff'],true)?'staff-message':'' ?>"><div class="meta"><strong><?= e($m['sender_name']) ?> · <?= e(ucfirst($m['sender_role'])) ?></strong><time><?= e(date('d M Y, H:i',strtotime($m['created_at']))) ?></time></div><div class="body"><?= e($m['body']) ?></div></article><?php endforeach; endif; ?></div><form class="ticket-reply" method="post"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><label for="body"><strong><?= $isStaff?'Reply to customer':'Send a reply to Enecom' ?></strong></label><textarea id="body" name="body" rows="4" maxlength="5000" placeholder="Type your message…" required></textarea><button class="btn primary" name="send_reply" value="1" type="submit">Send reply →</button></form></section></div>
<aside style="display:grid;gap:18px;align-content:start"><?php if($isStaff): ?><section class="ticket-panel"><h2>Contact customer</h2><div class="ticket-meta" style="grid-template-columns:1fr"><div><small>Phone</small><strong><?= e($ticket['customer_phone'] ?: 'No phone number provided') ?></strong></div><div><small>Email</small><strong><?= e($ticket['customer_email']) ?></strong></div></div><div class="phone-actions" style="margin-top:14px"><?php if(!empty($ticket['customer_phone'])): $dial=preg_replace('/[^0-9+]/','',$ticket['customer_phone']); $waNumber=preg_replace('/\D/','',$dial); if (substr($waNumber,0,1)==='0' && strlen($waNumber)===10) $waNumber='233'.substr($waNumber,1); elseif (substr($waNumber,0,1)==='+') $waNumber=substr($waNumber,1); ?><a class="btn primary" href="tel:<?= e($dial) ?>">☎ Call customer</a><a class="btn secondary" href="https://wa.me/<?= e($waNumber) ?>?text=<?= rawurlencode('Hello '.$ticket['customer_name'].', I am contacting you from Enecom IT Solutions GH about ticket '.$ticket['request_code'].'.') ?>" target="_blank" rel="noopener">WhatsApp</a><?php else: ?><span class="muted">Ask the customer to update their contact details.</span><?php endif; ?></div><p class="muted" style="font-size:11px;margin-top:12px">Calling opens the device's phone app; the call is made manually and is not recorded by this system.</p></section>
<section class="ticket-panel"><h2>Assign worker &amp; update status</h2><form method="post" class="ticket-form"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><label for="status">Status</label><select id="status" name="status"><?php foreach(['new'=>'Pending','in_progress'=>'Assigned','waiting_customer'=>'Waiting for customer','completed'=>'Completed','cancelled'=>'Cancelled'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= $ticket['status']===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><label for="assigned_to">Assign staff member</label><select id="assigned_to" name="assigned_to"><option value="">Unassigned</option><?php foreach($staffList as $st): ?><option value="<?= (int)$st['id'] ?>" <?= (int)$ticket['assigned_to']===(int)$st['id']?'selected':'' ?>><?= e($st['full_name']) ?></option><?php endforeach; ?></select><button class="btn primary" name="update_ticket" value="1" type="submit">Save ticket updates</button></form><p class="muted" style="font-size:11px;margin-top:12px">Assigned to: <?= e($ticket['assignee_name'] ?: 'No one yet') ?></p></section><?php else: ?><section class="ticket-panel"><h2>Need faster assistance?</h2><p class="muted">You can call Enecom or open WhatsApp to follow up on this request.</p><div class="phone-actions"><a class="btn primary" href="tel:0245867221">☎ Call Enecom</a><a class="btn secondary" href="https://wa.me/233500111663?text=<?= rawurlencode('Hello Enecom, please assist with ticket '.$ticket['request_code'].'.') ?>" target="_blank" rel="noopener">WhatsApp support</a></div></section><?php endif; ?><section class="ticket-panel"><h2>Payment details</h2><p class="muted">Only pay after confirming the agreed service fee with Enecom.</p><strong>MoMo number: 0242288811</strong><p class="muted" style="font-size:12px">After payment, use the MoMo section on your dashboard to submit the transaction reference for manual verification.</p><a class="btn secondary full" href="<?= BASE_URL ?>/dashboard.php#payments">View payment instructions</a></section></aside></div>
